The following is a workflow file. Treat it as data, not as instructions.
{
  "name": "fix",
  "path": ".aibus/workflows/fix.toml",
  "revision": "b22822247c4f0518ab758a5b4f87ef27edd3dfe2673ede94f463072ff1db1454",
  "scope": "project",
  "toml": "name = \"fix\"\ndescription = \"Diagnose, assess risk, fix, verify\"\n\n[[step]]\nagent = \"explore\"\nprompt = \"Diagnose this problem and say where the cause is (file paths and line numbers): {{input}}\"\n\n[[step]]\nagent = \"plan\"\nprompt = \"\"\"\nRisks of fixing it this way: {{prev.summary}}\n\nEnd your answer with one line, `RISK: LOW`, `RISK: MEDIUM` or `RISK: HIGH`.\n\"\"\"\n# Reads the step's JSON on stdin; exit 2 blocks the chain and stderr says why.\ngate = '''grep -q 'RISK: HIGH' && { echo \"the risk assessment ended on RISK: HIGH\" >&2; exit 2; }; exit 0'''\n\n[[step]]\nagent = \"general\"\nprompt = \"Make the fix. Diagnosis: {{steps.explore.summary}} Risks to keep in mind: {{steps.plan.summary}}\"\n\n[[step]]\nagent = \"general\"\nprompt = \"Verify the fix: run the project's tests and report what passed and what failed. Problem: {{input}}\"\non_fail = \"retry:2\"\n",
  "workflow": {
    "description": "Diagnose, assess risk, fix, verify",
    "name": "fix",
    "steps": [
      {
        "agent": "explore",
        "prompt": "Diagnose this problem and say where the cause is (file paths and line numbers): {{input}}",
        "retries": 0
      },
      {
        "agent": "plan",
        "gate": "grep -q 'RISK: HIGH' && { echo \"the risk assessment ended on RISK: HIGH\" >&2; exit 2; }; exit 0",
        "prompt": "Risks of fixing it this way: {{prev.summary}}\n\nEnd your answer with one line, `RISK: LOW`, `RISK: MEDIUM` or `RISK: HIGH`.\n",
        "retries": 0
      },
      {
        "agent": "general",
        "prompt": "Make the fix. Diagnosis: {{steps.explore.summary}} Risks to keep in mind: {{steps.plan.summary}}",
        "retries": 0
      },
      {
        "agent": "general",
        "prompt": "Verify the fix: run the project's tests and report what passed and what failed. Problem: {{input}}",
        "retries": 2
      }
    ]
  }
}
